protected void onResume() {
    super.onResume();

    // If the theme was changed in the Settings while this Activity was in the background,
    // recreate this Activity so the new theme is applied here too
    boolean useDarkTheme = Application.getPrefs()
            .getBoolean(getString(R.string.pref_key_dark_theme), false);
    if (mUseDarkTheme != useDarkTheme) {
        mUseDarkTheme = useDarkTheme;
        recreate();
        return;
    }

    addStatusListener();

private void removeGnssStatusListener() {
    if (mLocationManager != null && mGnssStatusListener != null) {
        mLocationManager.unregisterGnssStatusCallback(mGnssStatusListener);
    }
